function fsGauge() {
  /* 1.0.5.1 : l'Esprit Libre est supprimé ; la jauge montre la taille de l'équipe (plus elle est grande, plus chaque héros monte vite) */
  const team = E.team(S); const n = team.length; const syn = E.synergy(S);
  return `<div class="fsg ${n >= 8 ? "solo" : n ? "" : "zero"}" style="--p:${Math.round(n * 12.5)}" data-tip="Équipe : plus elle compte de héros, plus elle bat de monstres et plus chaque héros monte vite (8 héros montent bien plus vite qu'un héros seul). Synergie : +2 % de dégâts et d'XP par classe différente dans l'équipe (à partir de 2 héros).">
    <span class="flame"><i></i></span><span class="txt"><b>Équipe ${n}/8</b><br><span class="xs muted">${n ? (syn ? `Synergie +${syn} %` : "pas de synergie") : "aucun héros ne chasse"}</span><span class="pips5">${[1, 2, 3, 4, 5, 6, 7, 8].map((k) => `<i class="${k <= n ? "" : "off"}"></i>`).join("")}</span></span></div>`;
}
function questAlert() { if (window.QUI) return window.QUI.todo(S) > 0; return !!(S.almanax && S.almanax.day !== E.dayKey() && E.almanax(S).qty <= (S.res[E.almanax(S).res] || 0)); } // 0.1.28 : tout ce qui est prêt dans Quêtes (js/questui.js)
const jobImg = (j) => `assets/j/${j}.png`;
/* ---------- index des ressources : sources et usages ---------- */
let RIDX = null;
function resIndex() {
  if (RIDX) return RIDX; const src = {}, use = {};
  const add = (o, k, v) => (o[k] = o[k] || []).push(v);
  for (const k in MONSTERS) { const m = MONSTERS[k]; m.drops.forEach(([r, p]) => add(src, r, { m: k, p })); }
  for (const j in GATHER_JOBS) GATHER_JOBS[j].items.forEach(([r, l]) => add(src, r, { job: j, lvl: l }));
  for (const t in ITEMS) { const T = ITEMS[t]; if (T.craft) T.craft.ing.forEach(([r, q]) => add(use, r, { tpl: t, q })); }
  for (const n in SPECIAL_CRAFTS) SPECIAL_CRAFTS[n].ing.forEach(([r, q]) => add(use, r, { special: n, q }));
  for (const j in GATHER_JOBS) for (let L = 1; L <= E.TOOL_MAX; L++) E.toolRecipe(j, L).ing.forEach(([r, q]) => add(use, r, { tool: j, L, q }));
  for (const r in src) src[r].sort((a, b) => (b.p || 0) - (a.p || 0));
  return (RIDX = { src, use });
}
let ARCHI_BASE = null; // 1.0.8.4 : un archimonstre vit là où vit son monstre de base
const monHome = (k) => { if (!ARCHI_BASE) { ARCHI_BASE = {}; for (const b in MONSTERS) if (MONSTERS[b].archi) ARCHI_BASE[MONSTERS[b].archi] = b; } return ARCHI_BASE[k] || k; };
const subOfMon = (k) => { k = monHome(k); return Object.values(E.SUBS).find((s) => s.monsters.includes(k)) || (Object.entries(DUNGEONS).find(([, d]) => dgHasMon(d, k)) || [])[0]; };
const dgHasMon = (d, k) => d.boss === k || [].concat(d.coBoss || []).includes(k) || (d.bossMobs || []).includes(k) || d.rooms.some((r) => r.mobs.includes(k)); // boss, co-boss (les 4 Gelées Royales…), boss secondaires et salles
function bestSource(r) {
  if (E.RES_SOURCE && E.RES_SOURCE[r]) return E.RES_SOURCE[r];
  const L = resIndex().src[r] || []; const g = L.find((x) => x.job); if (g) return `${GATHER_JOBS[g.job].name} niv. ${g.lvl}`;
  const m = L.find((x) => x.m); if (!m) return r === E.RARE_COMPONENT ? "trouvailles de récolte, boss et coffres" : "source inconnue";
  const s = subOfMon(m.m); return `${MONSTERS[m.m].name}${s ? " (" + (typeof s === "string" ? DUNGEONS[s].name : s.name) + ")" : ""} · ${E.resRate(m.p).toFixed(1).replace(".", ",")} %`;
}
/* 0.1.53.5 : où aller chercher un monstre (zone de chasse visible d'abord, sinon son donjon) et monstres qui lâchent une ressource ou un objet */
function monWhere(k) {
  const base = Object.keys(MONSTERS).find((b) => MONSTERS[b].archi === k); if (base) { const w = monWhere(base); return w && Object.assign(w, { archi: true }); } // archimonstre : là où vit le monstre normal
  const subs = Object.values(E.SUBS).filter((s) => !s.hidden && (s.monsters || []).some((m) => (Array.isArray(m) ? m[0] : m) === k))
    .sort((a, b) => E.subUnlocked(S, b.id) - E.subUnlocked(S, a.id) || a.lvl[0] - b.lvl[0]); // zone ouverte d'abord, puis la plus basse
  if (subs.length) { const s0 = subs[0]; return { sub: s0.id, name: s0.name, lvl: `${s0.lvl[0]}–${s0.lvl[1]}`, open: E.subUnlocked(S, s0.id) }; }
  const dg = Object.keys(DUNGEONS).find((id) => { const d = DUNGEONS[id]; return d.boss === k || (d.bossMobs || []).includes(k) || d.rooms.some((r) => r.mobs.includes(k)); });
  return dg ? { dg, name: DUNGEONS[dg].name, lvl: String(DUNGEONS[dg].lvl), open: E.dungeonUnlocked(S, dg) } : null;
}
function dropMons(k, id, max) {
  const L = k === "res" ? (resIndex().src[id] || []).filter((x) => x.m).map((x) => ({ mon: x.m, p: E.resRate(x.p) }))
    : E.itemSources(id).filter((x) => x.mon).map((x) => ({ mon: x.mon, p: x.p }));
  return L.map((x) => Object.assign(x, { w: monWhere(x.mon) })).filter((x) => x.w).sort((a, b) => !!a.w.archi - !!b.w.archi).slice(0, max || 4); // archimonstres (rares) en dernier
}
/* 0.1.53.6 : une ligne « monstre » commune aux fiches ressource et objet : portrait, taux, zone (niveau, verrou) et bouton */
function monLineHtml(x, unknown) {
  const M = MONSTERS[x.mon]; const w = x.w;
  return `<div class="li monli ${w.open ? "" : "locked"}"><span class="icobox">${unknown ? `<b class="muted">?</b>` : im(imgM(x.mon), "", M.name)}</span><span class="grow"><b>${unknown ? "???" : h(M.name)}</b>${x.boss ? ` <span class="tag soft">boss</span>` : ""}${w.archi ? ` <span class="tag soft">archimonstre</span>` : ""}
    <span class="monwhere xs">${w.open ? IC("carte") : G("lock")} ${w.dg ? "Donjon · " : ""}${h(w.name)} · niv. ${w.lvl}</span></span><span class="monpct" data-tip="Chance de butin par monstre">${dropPct(x.p)} %</span><button class="btn sm ${w.open ? "primary" : ""}" ${monGoAttr(w)}>${w.dg ? "Donjon" : "Y aller"}</button></div>`;
}
/* 1.0.23.1 : où trouver la ressource d'une commande d'artisan : son métier de récolte, sinon la zone ouverte (ou le donjon) du monstre qui la lâche le plus */
function cmdGoBtn(r) {
  const g = (resIndex().src[r] || []).find((x) => x.job);
  if (g) return `<button class="btn sm" data-act="gathersheet" data-job="${g.job}" data-tip="${h(GATHER_JOBS[g.job].name)} niv. ${g.lvl}">${IC("pioche")} Récolter</button>`;
  const L = dropMons("res", r, 4); const x = L.find((y) => y.w.open && !y.w.archi) || L[0]; if (!x) return "";
  const tip = `${h(MONSTERS[x.mon].name)} · ${h(x.w.name)} · ${dropPct(x.p)} %`;
  return x.w.dg ? `<button class="btn sm" data-act="dgopen" data-id="${x.w.dg}" data-tip="${tip}">Donjon</button>` : `<button class="btn sm" data-act="zoneview" data-id="${x.w.sub}" data-gotab="world" data-tip="${tip}">${IC("carte")} Y aller</button>`;
}
const monGoAttr = (w) => (w.dg ? `data-act="searchdg" data-id="${w.dg}"` : `data-act="searchzone" data-id="${w.sub}"`);
const dropPct = (p) => (p >= 10 ? Math.round(p) : p >= 1 ? (+p).toFixed(1).replace(".", ",").replace(",0", "") : String(+(+p).toPrecision(2)).replace(".", ",")); // 1.0.15 : deux chiffres sous 1 % (0,045 %)
function shopIng(e) { return E.shopIng(S, e); }
function shopName(e) { return E.shopName(S, e); }
