function spellTip(sp, lvl) { const g = E.spellGrade(sp, lvl || 200); return `${sp.name} · ${g.pa} PA${g.cd ? ` · relance ${g.cd} tour${g.cd > 1 ? "s" : ""}` : ""}${g.casts ? ` · ${g.casts} lancer${g.casts > 1 ? "s" : ""}/tour` : ""} — ${spellText(sp, lvl)}`; }
