  const plate = mob ? 30 : 36, lift = rows <= 2 ? (mob ? 0.7 : 0.76) : 0.55;
  const step = mob ? Math.min(21, 41 / perRow) : Math.min(14, 41 / perRow), x0 = mob ? 40 : 43;
