// « Envoyer un héros » depuis un métier : d'abord un héros libre, puis un chasseur, puis un héros qui récolte ailleurs, jamais celui déjà sur ce métier
function gatherPick(job) {
  const busy = S.dungeon || (E.expActive && E.expActive(S));
  const rank = (c) => (c.job ? (c.job.job === job ? 5 : 4) : c.inTeam ? (busy ? 3 : 2) : (E.trainee(S) === c || E.atelierHero(S) === c ? 1 : 0));
  return S.chars.reduce((b, c) => (rank(c) < rank(b) || (rank(c) === rank(b) && c.id === ui.cid) ? c : b)).id;
}
function gatherSheet() {
  const g = ui.gs; const c = char(g.cid) || S.chars[0]; g.cid = c.id;
  if (!g.job) g.job = c.job ? c.job.job : "bucheron";
  const list = E.jobRes(g.job); const lv = S.jobs[g.job].lvl;
  if (!g.res || !list.find((x) => x[0] === g.res && x[1] <= lv)) g.res = (c.job && c.job.job === g.job ? c.job.res : null) || (list.filter((x) => x[1] <= lv).pop() || [])[0];
  const per = E.gatherPeriod(S, Object.assign({}, c, { job: { job: g.job, res: g.res, prog: 0 } }));
  openSheet(`<h2>${IC("pioche")} Envoyer récolter</h2>
    <p class="small muted">Le héros quitte l'équipe de chasse pendant qu'il récolte. Les niveaux de métier sont communs à tous vos héros.</p>
    <div class="stack" style="gap:8px">
      <label class="row small"><span style="min-width:90px">Héros</span><select data-act="gs" data-k="cid">${S.chars.map((x) => `<option value="${x.id}" ${x.id === c.id ? "selected" : ""}>${h(x.name)} (niv. ${x.lvl})${x.job ? " — récolte déjà" : ""}</option>`).join("")}</select></label>
      <div class="row small"><span style="min-width:90px">Métier</span>${Object.keys(GATHER_JOBS).map((j) => `<button class="jobpick ${j === g.job ? "on" : ""}" data-act="gsjob" data-v="${j}" data-tip="${h(GATHER_JOBS[j].name)} niv. ${S.jobs[j].lvl}">${im(jobImg(j), "joblogo sm", GATHER_JOBS[j].name)}</button>`).join("")}</div>
      <div class="respick">${list.map(([r, l]) => `<button class="${r === g.res ? "on" : ""}" data-act="gsres" data-v="${h(r)}" ${l > lv ? "disabled" : ""} data-tip="${h(r)} · niveau ${l}${l > lv ? " (verrouillé)" : ""} · en stock : ${fmt(S.res[r] || 0)}">${im(resImg(r), "ico", r)}<span class="xs">${h(r)}</span>${l > lv ? `<i class="xs">niv. ${l}</i>` : ""}</button>`).join("")}</div>
      ${g.res ? `<div class="small muted">coup de ${hitDur(per)} · ≈ ${fmt(Math.max(1, Math.round(E.hitQty(S, Object.assign({}, c, { job: { job: g.job, res: g.res, prog: 0 } })))))} ${h(g.res)} par coup${E.filonOn(S, g.res) ? " · <b class='plus'>filon actif ×2 !</b>" : ""}${c.cls === "sadi" && (g.job === "bucheron" || g.job === "alchimiste") ? " · passif Sadida" : ""}${c.cls === "steam" && g.job === "pecheur" ? " · passif Steamer" : ""}</div>` : ""}
    </div>
    <div class="row"><button class="btn primary" data-act="gsgo" ${g.res ? "" : "disabled"}>Envoyer</button>${c.job ? `<button class="btn" data-act="unjob" data-id="${c.id}">Rappeler pour chasser</button>` : ""}<button class="btn" data-act="closesheet">Annuler</button></div>`);
}
/* ---------- 3.2.2 : notifications ---------- */
const NOTIF_EV = [["bag", "Sac plein", "les nouveaux objets vont dans le trop-plein"], ["loss", "Combat perdu", "avec le conseil « Pourquoi j'ai perdu ? »"], ["pin", "Objectif atteint", "un objectif de la bande du haut"], ["shop", "Liste de courses prête", "tout est réuni pour un objet ou une clé"], ["lvl", "Palier de niveau", "tous les 10 niveaux"], ["rare", "Évènement rare", "Champion, objet Rayonnant ou archimonstre"]];
const NOTIF_DEF = { bag: true, loss: true, pin: true, shop: true, lvl: true, rare: false };
const notifOn = (k) => { const n = S.settings.notif || {}; return n[k] === undefined ? NOTIF_DEF[k] : !!n[k]; };
const notifPerm = () => (typeof Notification === "undefined" ? "none" : Notification.permission);
function notifOptionsHtml() {
  const perm = notifPerm(); const on = !!S.settings.notifBrowser && perm === "granted";
  return optSec(`${G("bell")} Notifications`, "un petit message dans le jeu, et une notification du navigateur quand l'onglet est en arrière-plan",
      optLine("Hors de l'onglet", "", perm === "none" ? `<span class="tag soft">Non disponible sur ce navigateur</span>` : perm === "denied" ? `<span class="tag warn">Bloquées par le navigateur</span><span class="xs muted">autorisez-les dans les réglages du site</span>` : perm === "granted" ? `<span class="seg">${[[true, "Activées"], [false, "Coupées"]].map(([v, n]) => `<button data-act="setnotifb" data-v="${v ? 1 : 0}" aria-pressed="${on === v}">${n}</button>`).join("")}</span>` : `<button class="btn sm primary" data-act="notifask">Autoriser</button>`)
    + `<div class="notifs">${NOTIF_EV.map(([k, n, d]) => `<label class="opt"><span><b>${h(n)}</b><br><span class="xs muted">${h(d)}</span></span><input type="checkbox" data-act="setnotif" data-k="${k}" ${notifOn(k) ? "checked" : ""}></label>`).join("")}</div>
    <p class="xs muted" style="margin:0">Fiable sur ordinateur. Sur téléphone, seulement tant que l'onglet reste ouvert (sur iPhone, uniquement si le jeu est installé sur l'écran d'accueil). Au plus une notification par minute.</p>`);
}
let notifLast = 0, notifHeld = [];
function notify(kind, title, body) {
  if (!S || !notifOn(kind)) return;
  if (!S.settings.notifBrowser || notifPerm() !== "granted" || document.visibilityState === "visible") return;
  const now = Date.now();
  if (now - notifLast < 60000) { notifHeld.push(title); clearTimeout(notify._to); notify._to = setTimeout(() => { const n = notifHeld.length; if (!n) return; const t = n === 1 ? notifHeld[0] : `${n} évènements pendant votre absence`; notifHeld = []; showNotif(t, n === 1 ? body : ""); }, 60000 - (now - notifLast) + 50); return; }
  notifLast = now; showNotif(title, body);
}
function showNotif(title, body) {
  if (document.visibilityState === "visible") return;
  const opts = { body: body || "", icon: "icons/icon-192.png", badge: "icons/icon-192.png", tag: "idlus", renotify: false, silent: true };
  try { if (navigator.serviceWorker && navigator.serviceWorker.controller) navigator.serviceWorker.ready.then((r) => r.showNotification(`idlus · ${title}`, opts)).catch(() => { try { new Notification(`idlus · ${title}`, opts); } catch (e) {} }); else new Notification(`idlus · ${title}`, opts); } catch (e) {}
}
/* 0.1.25 : les Options rangées en onglets ; une carte par thème, chaque réglage sur une ligne (nom et explication à gauche, choix à droite) */
const OPT_TABS = [["affichage", "Affichage"], ["sons", "Sons"], ["jeu", "Jeu"], ["sauvegarde", "Sauvegarde"], ["aide", "Aide"]];
const optSec = (t, hint, body, id) => `<section class="optsec"${id ? ` id="${id}"` : ""}><div class="optsec-h"><b>${t}</b>${hint ? `<span class="xs muted">${hint}</span>` : ""}</div>${body}</section>`;
const optName = (n, hint, tip) => `<span class="optname"${tip ? ` data-tip="${h(tip)}"` : ""}><b>${n}</b>${hint ? `<span class="xs muted">${hint}</span>` : ""}</span>`;
const optLine = (n, hint, ctl, tip) => `<div class="optline">${optName(n, hint, tip)}<span class="optctl">${ctl}</span></div>`;
const optChk = (attrs, on, n, hint) => `<label class="optline optchk">${optName(n, hint)}<input type="checkbox" ${attrs} ${on ? "checked" : ""}></label>`;
const optChkBtn = (attrs, on, n, hint, btn) => `<label class="optline optchk">${optName(n, hint)}<span class="optctl">${btn}<input type="checkbox" ${attrs} ${on ? "checked" : ""}></span></label>`; // 1.0.30 : case à cocher et bouton « Écouter »
