const halOn = () => halPeriod() && !(S && S.settings.halouine === false);
const HAL_EMB = [[6, 15, 0], [13, 19, -7], [21, 13, -3], [29, 17, -12], [36, 14, -5], [44, 20, -15], [51, 16, -1], [58, 13, -9], [65, 18, -4], [72, 15, -13], [79, 21, -6], [86, 14, -10], [92, 17, -2], [97, 19, -16]];
