  if (emb && !fx) { fx = document.createElement("div"); fx.id = "halfx"; fx.setAttribute("aria-hidden", "true"); fx.innerHTML = HAL_EMB.map(([x, d, dl]) => `<i style="left:${x}%;--d:${d}s;--dl:${dl}s"></i>`).join(""); document.body.appendChild(fx); }
