      const v = ($("#onRenPseudo").value || "").trim(); ui.prenVal = v; const old = ON.profile.pseudo;
      const bad = v === old ? null : ON.pseudoProblem(v); if (bad) { ui.prenErr = bad; optionsSheet(); return; }
