  jobGoal(out, me, (a, b) => (!all ? [jobTot(G, a.l, a.x, a.r) - jobTot(G, b.l, b.x, b.r) + 1, "XP"] : a.r > b.r ? [a.r - b.r, "renaissance"] : a.r < b.r ? [0, ""] : a.l > b.l ? [a.l - b.l + 1, "niveau"] : [a.x - b.x + 1, "XP"]));
